2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	
12	/**
13	 * Assigns the {@code householdId} when the request opts into sharing a household
14	 * ({@code sharesHousehold} true). The identifier is a stable value derived deterministically
15	 * from the household identity — the {@code lastName} and {@code address} normalized the same
16	 * way {@link RequireUniqueOwnerHousehold} compares them (case-insensitive, whitespace
17	 * collapsed) — so every owner of the same household is assigned the same value regardless of
18	 * creation order.
19	 *
20	 * <p>Any existing owners already in that household are back-filled with the same identifier,
21	 * so both the joining owner and the owners already there carry it.
22	 *
23	 * <p>When {@code sharesHousehold} is not true, no identifier is assigned and the owner keeps
24	 * a null {@code householdId}.
25	 */
26	public class AssignHouseholdId {
27	
28	    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
29	            OwnerRepository ownerRepository) {
30	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
31	            return;
32	        }
33	        String lastName = RequireUniqueOwnerHousehold.normalize(owner.getLastName());
34	        String address = RequireUniqueOwnerHousehold.normalize(owner.getAddress());
35	        String householdId = deriveHouseholdId(lastName, address);
36	        owner.setHouseholdId(householdId);
37	        for (Owner existing : ownerRepository.findAll()) {
38	            if (RequireUniqueOwnerHousehold.normalize(existing.getLastName()).equals(lastName)
39	                    && RequireUniqueOwnerHousehold.normalize(existing.getAddress()).equals(address)
40	                    && !householdId.equals(existing.getHouseholdId())) {
41	                existing.setHouseholdId(householdId);
42	                ownerRepository.save(existing);
43	            }
44	        }
45	    }
46	
47	    /** {@code HH-} followed by the first 16 upper-case hex chars of SHA-256(lastName|address). */
48	    static String deriveHouseholdId(String lastName, String address) {
49	        String key = lastName + "|" + address;
50	        try {
51	            byte[] digest = MessageDigest.getInstance("SHA-256")
52	                    .digest(key.getBytes(StandardCharsets.UTF_8));
53	            StringBuilder sb = new StringBuilder("HH-");
54	            for (int i = 0; i < 8; i++) {
55	                sb.append(String.format("%02X", digest[i]));
56	            }
57	            return sb.toString();
58	        }
59	        catch (NoSuchAlgorithmException ex) {
60	            throw new IllegalStateException("SHA-256 not available", ex);
61	        }
62	    }
63	}
